import{_ as s,C as a,c as n,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Routes and rules","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/routes/routes-and-rules.md","filePath":"master/supply-chain/inventories/routes/routes-and-rules.md","lastUpdated":1792041590000}'),l={name:"master/supply-chain/inventories/routes/routes-and-rules.md"};function u(d,e,h,g,c,p){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="routes-and-rules" tabindex="-1">Routes and rules <a class="header-anchor" href="#routes-and-rules" aria-label="Permalink to &quot;Routes and rules&quot;">​</a></h1><p>Routes and rules are the engine behind every flow in Aureus. A rule describes one step: where goods come from, where they go and which document is created. A route groups several rules under one name. Most users never edit them, but understanding them helps you fix unusual flows.</p><blockquote><p><strong>In simple words:</strong> A rule is one step. A route is a named list of steps.</p></blockquote><p>Open them from <code>Inventory → Configurations → Warehouse Management → Routes</code> and <code>→ Rules</code>.</p><div class="warning custom-block"><p class="custom-block-title">Gate</p><p>These menus appear only when <code>Inventory → Settings → Manage Warehouses → Multi Steps Routes</code> is on. Locations must be on too.</p></div><div class="warning custom-block"><p class="custom-block-title">Careful with standard rules</p><p>Aureus creates standard routes and rules for each warehouse. Do not edit or delete them. Change the step options on the warehouse form instead. Test any new rule on a sample order first.</p></div><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h2><p>The <strong>Routes</strong> list shows <strong>Route</strong> and <strong>Company</strong>, with tabs <strong>All</strong> and <strong>Archived</strong>. There are 4 active routes, and the <strong>Archived</strong> tab holds 3. Click <strong>New Route</strong>.</p>',8)),r(o,{src:"/images1/inventory/route_list.png",alt:"Routes list on the All tab with 4 active routes: Receive in 3 steps, Deliver in 3 steps, Pick components and manufacture, and Cross-Dock"}),e[1]||(e[1]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Route:</em></strong> required. A clear name, for example Two Step Reception.</li><li><strong><em>Company:</em></strong> defaults to your company.</li></ul><h3 id="applicable-on" tabindex="-1">Applicable On <a class="header-anchor" href="#applicable-on" aria-label="Permalink to &quot;Applicable On&quot;">​</a></h3><p>Choose where people can pick this route. The toggles are <strong>Product Categories</strong>, <strong>Products</strong> and <strong>Packaging</strong>, with <strong>Warehouses</strong> in a second column.</p><ul><li><strong><em>Product Categories:</em></strong> the route can be set on a product category.</li><li><strong><em>Products:</em></strong> the route can be set on a product.</li><li><strong><em>Packaging:</em></strong> the route can be set on a packaging. The toggle always shows.</li><li><strong><em>Warehouses:</em></strong> the route becomes a default for a warehouse. A <strong>Warehouses</strong> list then appears. This toggle sits in the second column.</li></ul>',5)),r(o,{src:"/images1/inventory/route_form.png",alt:"New Route form with the name Two Step Reception and the Applicable On toggles"}),e[2]||(e[2]=t('<p>The route page also has a <strong>Rules</strong> table. Click <strong>Add Rule</strong> to attach a step.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>The <strong>Rules</strong> list shows <strong>Action</strong>, <strong>Source Location</strong>, <strong>Destination Location</strong>, <strong>Route</strong> and <strong>Name</strong>. Click <strong>New Rule</strong>.</p>',3)),r(o,{src:"/images1/inventory/route_rule_form.png",alt:"New Rule form with action Pull From, operation type Pick and source WH/Stock"}),e[3]||(e[3]=t('<h3 id="general-1" tabindex="-1">General <a class="header-anchor" href="#general-1" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> required.</li><li><strong><em>Action:</em></strong> required. See the table below.</li><li><strong><em>Operation Type:</em></strong> required. The document the step creates. Options are named with the warehouse first, for example <strong>My Company: Pick</strong>.</li><li><strong><em>Source Location</em> and <em>Destination Location:</em></strong> required. Where goods leave and arrive.</li><li><strong><em>Supply Method:</em></strong> how a pull gets goods. Hidden for Push To.</li><li><strong><em>Automatic Move:</em></strong> how a push behaves. Hidden for Pull From.</li></ul><p>A live sentence beside <strong>Action</strong> explains the rule in plain words, for example &quot;When products are required in X, Y is generated from Z...&quot;. These labels sit on the left of the form. The <strong>Settings</strong> card sits on the right.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pull From</strong></td><td>Goods are requested from the source when needed</td></tr><tr><td><strong>Push To</strong></td><td>Goods that reach the source are sent on to the destination</td></tr><tr><td><strong>Pull &amp; Push</strong></td><td>Both behaviours</td></tr><tr><td><strong>Buy</strong></td><td>A request for quotation is created for the need</td></tr><tr><td><strong>Manufacture</strong></td><td>A manufacturing order is created for the need</td></tr></tbody></table><h3 id="supply-method" tabindex="-1">Supply Method <a class="header-anchor" href="#supply-method" aria-label="Permalink to &quot;Supply Method&quot;">​</a></h3><ul><li><strong>Take From Stock:</strong> use goods already in the source location.</li><li><strong>Trigger Another Rule:</strong> ignore stock and find another rule to bring goods in.</li><li><strong>Take From Stock, if unavailable, Trigger Another Rule:</strong> use stock first, then fall back.</li></ul><h3 id="automatic-move" tabindex="-1">Automatic Move <a class="header-anchor" href="#automatic-move" aria-label="Permalink to &quot;Automatic Move&quot;">​</a></h3><ul><li><strong>Manual Operation:</strong> creates a separate move after the current one.</li><li><strong>Automatic No Step Added:</strong> changes the location of the original move. No extra document.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>The <strong>Settings</strong> card on the right holds these fields.</p><ul><li><strong><em>Partner Address:</em></strong> delivery address, optional. Shown for pulls.</li><li><strong><em>Lead Time (Days):</em></strong> used to calculate the expected date of the transfer.</li><li><strong>Applicability:</strong> a box inside the card with two fields. <ul><li><strong><em>Route</em>:</strong> required. The route this rule belongs to.</li><li><strong><em>Company:</em></strong> defaults to your company.</li></ul></li></ul><h2 id="two-worked-rules" tabindex="-1">Two worked rules <a class="header-anchor" href="#two-worked-rules" aria-label="Permalink to &quot;Two worked rules&quot;">​</a></h2><p><strong>Push rule: Input → Quality Control.</strong> Action <strong>Push To</strong>, operation type <strong>Quality Control</strong>, source <code>WH/Input</code>, destination <code>WH/Quality Control</code>. When a receipt lands in <code>WH/Input</code>, a WH/QC document is created.</p><p><strong>Pull rule: Stock → Customers.</strong> Action <strong>Pull From</strong>, operation type <strong>Pick</strong>, supply method <strong>Take From Stock</strong>. When a customer order asks for goods, a WH/PICK document is created.</p><h2 id="apply-a-route" tabindex="-1">Apply a route <a class="header-anchor" href="#apply-a-route" aria-label="Permalink to &quot;Apply a route&quot;">​</a></h2><ol><li>Open a product, a product category or a packaging.</li><li>Find the <strong>Routes</strong> field in its Inventory section.</li><li>Pick the route and save.</li></ol>',17)),r(o,{src:"/images1/inventory/route_on_product.png",alt:"Product Inventory section with the Routes field showing Cross-Dock"}),e[4]||(e[4]=t('<p>The route only appears in the list if its <strong>Applicable On</strong> toggle matches. See <a href="./../products/product-categories.html">Product categories</a> and <a href="./../products/configure-product.html">Configure a product</a>.</p><h2 id="warehouse-routes-page" tabindex="-1">Warehouse Routes page <a class="header-anchor" href="#warehouse-routes-page" aria-label="Permalink to &quot;Warehouse Routes page&quot;">​</a></h2><p>The warehouse record has a <strong>Routes</strong> tab. It opens a page titled <strong>Manage My Company Routes</strong>. The page lists 3 routes: <strong>Pick components, manufacture and then store products (3 steps)</strong>, <strong>Deliver in 3 steps</strong> and <strong>Receive in 3 steps</strong>. <strong>Cross-Dock</strong> is not on it. The page has an <strong>Add Route</strong> button.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Routes overview</a></li><li><a href="./putaway-rules.html">Putaway rules</a></li><li><a href="./../warehouses/warehouses.html">Warehouses</a></li><li><a href="./../warehouses/operation-types.html">Operation types</a></li></ul>',5))])}const b=s(l,[["render",u]]);export{f as __pageData,b as default};
